    private static final String BASE_DIR = "/tmp/upload";

    public boolean writeFileContent(String filePath, String content) {
        if (filePath == null || filePath.trim().isEmpty()) {
            return false;
        }

        try {
            Path baseDir = Paths.get(BASE_DIR).toAbsolutePath().normalize();

            // Ensure base directory exists and is not a symbolic link to prevent base path hijacking
            if (Files.exists(baseDir, LinkOption.NOFOLLOW_LINKS)) {
                if (Files.isSymbolicLink(baseDir)) {
                    return false;
                }
            } else {
                Files.createDirectories(baseDir);
            }

            // Resolve the real path of the base directory
            baseDir = baseDir.toRealPath();

            // Resolve and normalize the target path
            Path targetPath = baseDir.resolve(filePath).toAbsolutePath().normalize();

            // Prevent path traversal attacks
            if (!targetPath.startsWith(baseDir)) {
                return false;
            }

            // Prevent writing to the base directory itself
            if (targetPath.equals(baseDir)) {
                return false;
            }

            // Check for symbolic link traversal in existing path components
            Path current = baseDir;
            Path relative = baseDir.relativize(targetPath);
            for (Path part : relative) {
                current = current.resolve(part);
                if (Files.exists(current, LinkOption.NOFOLLOW_LINKS)) {
                    if (Files.isSymbolicLink(current)) {
                        Path real = current.toRealPath();
                        if (!real.startsWith(baseDir)) {
                            return false;
                        }
                    }
                }
            }

            // Create parent directories if they don't exist
            Path parent = targetPath.getParent();
            if (parent != null && !Files.exists(parent)) {
                Files.createDirectories(parent);
            }

            // Handle null content gracefully
            String text = content == null ? "" : content;

            // Write content to file (creates if not exists, overwrites if exists)
            Files.write(targetPath, text.getBytes(StandardCharsets.UTF_8), 
                        StandardOpenOption.CREATE, 
                        StandardOpenOption.TRUNCATE_EXISTING, 
                        StandardOpenOption.WRITE);

            return true;
        } catch (IOException | InvalidPathException | SecurityException e) {
            // Handles permission issues, invalid paths, and other IO errors
            return false;
        } catch (Exception e) {
            // Fallback for any unexpected runtime exceptions
            return false;
        }
    }
}
